import{_ as a,o as s,c as t,ao as i}from"./chunks/framework.DcztfwHe.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":null}'),n={name:"getting-started.md"};function o(r,e,h,l,d,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="Getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#Getting-started" aria-label="Permalink to &quot;Getting started {#Getting-started}&quot;">​</a></h1><h2 id="Requirements" tabindex="-1">Requirements <a class="header-anchor" href="#Requirements" aria-label="Permalink to &quot;Requirements {#Requirements}&quot;">​</a></h2><ul><li><p><a href="https://julialang.org/downloads/" target="_blank" rel="noreferrer">Julia</a>, installed with <a href="https://github.com/JuliaLang/juliaup" target="_blank" rel="noreferrer">juliaup</a> if you want to compare Julia versions (<code>-v</code>).</p></li><li><p>A bash shell. On Ubuntu, <code>sh</code> is <code>dash</code>, which fails on <code>benchmark.sh</code> with <code>Bad substitution</code>: run the scripts as <code>./benchmark.sh</code> or <code>bash benchmark.sh</code>. On Windows, use Git Bash.</p></li><li><p><code>git</code> and <a href="https://git-lfs.com/" target="_blank" rel="noreferrer">git-lfs</a>, for the developed-flow checkpoints.</p></li><li><p>A clone of <a href="https://github.com/WaterLily-jl/WaterLily.jl" target="_blank" rel="noreferrer">WaterLily.jl</a>. Point <code>WATERLILY_DIR</code> to it, or pass <code>-wd &lt;path&gt;</code>. With <code>-w</code>, <code>benchmark.sh</code> checks out each requested ref in that clone, so keep its working tree clean.</p></li><li><p>For the GPU backends, an NVIDIA GPU with its driver (<code>CuArray</code>) or an AMD GPU with ROCm (<code>ROCArray</code>).</p></li></ul><h2 id="Install" tabindex="-1">Install <a class="header-anchor" href="#Install" aria-label="Permalink to &quot;Install {#Install}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/WaterLily-jl/WaterLily-Benchmarks</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WaterLily-Benchmarks</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WATERLILY_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/path/to/WaterLily.jl</span></span></code></pre></div><p>The checkpoints take about 1 GB. To download only the ones you use, clone with <code>GIT_LFS_SKIP_SMUDGE=1 git clone ...</code>: the checkpoints are then small git-LFS pointers, and <code>benchmark.sh</code> fetches the ones a sweep needs.</p><h2 id="First-benchmark" tabindex="-1">First benchmark <a class="header-anchor" href="#First-benchmark" aria-label="Permalink to &quot;First benchmark {#First-benchmark}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./benchmark.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare.jl</span></span></code></pre></div><p>This runs the default sweep on the current state of <code>$WATERLILY_DIR</code> and the current <code>julia</code>: the <code>tgv</code> (at <code>log2p = 6,7</code>) and <code>jelly-biotsavart</code> (<code>5,6</code>) cases, 25 steps, <code>Float32</code>, on the CPU with 4 threads and on an NVIDIA GPU (the default backends, <code>-b &quot;Array CuArray&quot;</code>). Without an NVIDIA GPU, run on the CPU only with <code>-b Array</code>. The first run installs the benchmark environment and develops WaterLily from <code>$WATERLILY_DIR</code> into it, and the first GPU run makes the GPU environment (see <a href="./environments">Environments</a>). Add <code>-u true</code> to update them when the Julia version or the WaterLily dependencies change (see <a href="/WaterLily-Benchmarks/previews/PR49/benchmarks#Updating-the-environment">Updating the environment</a>).</p><p><code>benchmark.sh</code> writes one JSON file per case and backend into <code>data/benchmark/&lt;hostname&gt;_&lt;WaterLily hash&gt;/</code>, and <code>compare.jl</code> prints one table per case and size. <a href="./methodology">Methodology</a> explains the columns.</p><p>On a laptop, or any machine whose clock speed changes with temperature or power, add <code>-r 3</code> to repeat the sweep in separate processes: a single process cannot measure that scatter (see <a href="/WaterLily-Benchmarks/previews/PR49/methodology#Noise-and-repetitions">Noise and repetitions</a>). On Linux, <code>benchmark.sh</code> also checks the machine first and stops if a CPU is capped below its maximum frequency (see <a href="/WaterLily-Benchmarks/previews/PR49/benchmarks#Machine-check">Machine check</a>).</p><h2 id="Comparing-WaterLily-versions" tabindex="-1">Comparing WaterLily versions <a class="header-anchor" href="#Comparing-WaterLily-versions" aria-label="Permalink to &quot;Comparing WaterLily versions {#Comparing-WaterLily-versions}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./benchmark.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;master my-branch&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Array</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1 4&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --speedup_base=master</span></span></code></pre></div><p><code>-w</code> takes branches, tags or commit hashes, and <code>-b Array -t &quot;1 4&quot;</code> runs on the CPU with 1 and 4 threads. To also run on a GPU, add its backend to <code>-b</code>: <code>-b &quot;Array CuArray&quot;</code> for NVIDIA, <code>-b &quot;Array ROCArray&quot;</code> for AMD. The <code>Δ ± σ</code> and <code>Signif</code> columns compare each row with the <code>master</code> row of the same backend. See <a href="./benchmarks">Running benchmarks</a> for all the options of <code>benchmark.sh</code> and <a href="./compare">Comparing results</a> for <code>compare.jl</code>.</p><h2 id="Plotting" tabindex="-1">Plotting <a class="header-anchor" href="#Plotting" aria-label="Permalink to &quot;Plotting {#Plotting}&quot;">​</a></h2><p><code>compare.jl --plot_dir=plots</code> also saves the cost and speedup plots as PDF. The plotting packages are in their own environment, so that benchmarking never installs them. Instantiate it once:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=plotting</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span></code></pre></div>`,17)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
